def create_wrapper():
    # This function simulates being in a different module
    # We use a closure to simulate different globals
    def wrapper_factory(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapper
    return wrapper_factory

wrap_foo = create_wrapper()(foo)

try:
    sig = get_typed_signature(wrap_foo)
    print('Success:', sig)
except NameError as e:
    print('Failed: NameError:', e)
except Exception as e:
    print('Error:', type(e), e)
